    def _prepare_published_q_for_stopped_preflight(self, *, with_image=False, no_upgrade=False,
                                                  ztp_disabled=False, seed_q_publication=False,
                                                  publication_phase="published", partial_runtime=False,
                                                  q_local=False, original_a_policy=None, original_a_images=False,
                                                  q_created=False, dhcp=False, dhcp_metadata=False, prefix=False,
                                                  managed_key=False, prefix_change=False, qualified_a_health=False):
        state, context, guard = self._prepare_q_manifest_publication(seed_q_publication=seed_q_publication,
            q_local=q_local, original_a_policy=original_a_policy, original_a_images=original_a_images,
            q_created=q_created, prefix=prefix or prefix_change, managed_key=managed_key,
            prefix_change=prefix_change, qualified_a_health=qualified_a_health)
        q = state[1]
        for name, source in (("01-global.yaml", self.inputs.global_file),
                             ("02-devices_config.csv", self.inputs.devices_file),
                             ("02-dhcp-subnet_config.csv", self.inputs.subnet_file),
                             ("p2p-original.xlsx", self.inputs.p2p_file)):
            (q / name).write_bytes(source.read_bytes())
        if seed_q_publication:
            (q / "p2p.xlsx").unlink()  # This fixture's previous Q alias, not an unknown production object.
        (q / "p2p.xlsx").symlink_to("p2p-original.xlsx")
        document = yaml.safe_load((q / "01-global.yaml").read_text())
        if prefix_change:
            document["common"]["mgmt"]["ztp"]["ztp_url_prefix"] = prefix_change if isinstance(prefix_change, str) else "/q-prefix"
        document["common"]["mgmt"]["dhcp-server"]["status"] = "disabled"
        if ztp_disabled:
            document["common"]["mgmt"]["ztp"]["status"] = "disabled"
            document["common"]["mgmt"]["http"]["status"] = "enabled"
        if with_image:
            document["switches"][0]["eth"]["version"] = "5.12.0"
        (q / "01-global.yaml").write_text(yaml.safe_dump(document, sort_keys=False))
        (q / "02-dhcp-subnet_config.csv").write_text(
            "shared_network,subnet,netmask,range_start,range_end,routers,ztp_service_ip,cumulus_profile,nvos_ztp\n"
            "net,192.0.2.0,255.255.255.0,192.0.2.100,192.0.2.120,192.0.2.1,192.0.2.40,oob,no\n")
        inputs = LOAD.replace(self.inputs, global_file=q / "01-global.yaml",
            devices_file=q / "02-devices_config.csv", subnet_file=q / "02-dhcp-subnet_config.csv",
            p2p_file=q / "p2p-original.xlsx", settings=LOAD.load_global(q / "01-global.yaml"),
            source_identities=None)
        image_options = {}
        if no_upgrade:
            image_options = dict(images={}, upgrade_enabled=False)
        if with_image:
            basename = "cumulus-linux-5.12.0-mlx-amd64.bin"
            source = self.root / basename
            source.write_bytes(b"#!/bin/sh\n" + b"x" * 1048576)
            published = self.ztp / "image/cumulus" / basename
            published.parent.mkdir(parents=True)
            published.write_bytes(source.read_bytes())
            image_options["images"] = {"eth": source}
        if partial_runtime:
            (self.ztp / "ztp-bootstrap_oob.sh").write_bytes(b"independent partially installed B runtime\n")
        candidates = private_publication_candidates(LOAD, q)
        with mock.patch.object(LOAD, "active_managed_services", return_value=()), ExitStack() as namespaces:
            if prefix_change:
                LOAD.configure_ztp_prefix_publication(inputs.settings, setup_guard=guard)
            if dhcp:
                names = ("dhcpd.conf", "dhcpd_eth.hosts", "dhcpd_ib.hosts", "dhcpd_nvl.hosts")
                namespaces.enter_context(mock.patch.object(LOAD, "dhcp_file_mappings", return_value={
                    q / "independent-dhcp-B" / name: self.root.resolve() / "private-etc-dhcp" / name
                    for name in names}))
            token = LOAD.register_setup_switch_publication_bundle(*candidates, guard=guard, **image_options)
            self.addCleanup(LOAD.close_setup_switch_publication_bundle, token)
            if dhcp:
                assert_private_dhcp_transaction_retention(LOAD, self.root, q, "bound-setup-before-write",
                    setup_guard=guard, publication_candidates=(*candidates, token), a_shapes=True,
                    a_metadata=dhcp_metadata)
            else:
                LOAD.commit_prepared_release(candidates[0], require_authority=lambda:
                    LOAD.require_setup_switch_publication_bundle(token, guard=guard))
            if publication_phase != "report":
                LOAD.generation_report.commit_prepared_generation_report(candidates[1], require_authority=lambda:
                    LOAD.require_setup_switch_publication_bundle(token, guard=guard, phase="report"))
            if publication_phase == "published":
                selector = json.loads(token["payload"])["body"]["publication_bundle"]["selector"]
                LOAD.commit_pinned_generation(q, candidates[2],
                    expected_current=self._original_q_publication["selector"] if seed_q_publication else None,
                    prepared_selector=selector["staged"], require_authority=lambda:
                    LOAD.require_setup_switch_publication_bundle(token, guard=guard, phase="selector"))
        return state, context, guard, token, inputs

