    def test_dhcp_live_candidate_inventory_closed_fields_boolean_escape_and_original_absence(self):
        state, _context, _guard, _token, _inputs = self._prepare_published_q_for_stopped_preflight(dhcp=True)
        original = json.loads(state[-3].read_bytes())["body"]["dhcp_transaction"]
        for fault in ("boolean", "extra", "escape", "absent-owner", "mode"):
            with self.subTest(fault=fault):
                binding = json.loads(json.dumps(original))
                inventory = binding["live_inventory"]
                if fault == "boolean":
                    inventory["after"]["dhcpd.conf"]["file"]["identity"][0] = True
                elif fault == "extra":
                    inventory["after"]["independent-unregistered-leaf"] = inventory["after"]["dhcpd.conf"]
                elif fault == "escape":
                    inventory["after"]["dhcpd.conf"]["path"] = str(self.root / "independent-unregistered-stage")
                elif fault == "absent-owner":
                    inventory["restore"]["dhcpd_nvl.hosts"] = inventory["restore"]["dhcpd.conf"]
                else:
                    inventory["after"]["dhcpd.conf"]["file"]["state"]["mode"] = 0o600
                with self.assertRaises(ValueError):
                    LOAD._validate_setup_switch_dhcp_live_inventory(binding)

    def _committed_q_group_dhcp_stage_fault(self, unknown):
        state, _context, guard, _token, _inputs = self._prepare_published_q_for_stopped_preflight(dhcp=True)
        q, journal = state[1], state[-3]
        runtime = self.root.resolve() / "private-etc-dhcp"
        names = ("dhcpd.conf", "dhcpd_eth.hosts", "dhcpd_ib.hosts", "dhcpd_nvl.hosts")
        mappings = {q / "independent-dhcp-B" / name: runtime / name for name in names}
        with mock.patch.object(LOAD, "active_managed_services", return_value=()), \
                mock.patch.object(LOAD, "dhcp_file_mappings", return_value=mappings):
            LOAD.restore_setup_switch_q_publication(q, guard=guard, confirmed=True)
            marker = journal.parent / ".setup-switch-a-restore.json"
            if unknown:
                stage = runtime / (".r22-a-dhcp-" + "1" * 32)
                stage.write_bytes(b"independent unknown stage retained\n")
            else:
                stage = Path(json.loads(marker.read_bytes())["dhcp"][str(runtime / "dhcpd.conf")]["stage"]["path"])
                metadata, payload = stage.lstat(), stage.read_bytes()
                held = self.root / "independent-held-dhcp-restore-stage"
                stage.rename(held)
                stage.write_bytes(payload)
                stage.chmod(stat.S_IMODE(metadata.st_mode))
                os.utime(stage, ns=(metadata.st_atime_ns, metadata.st_mtime_ns))
                self.assertNotEqual(held.lstat().st_ino, stage.lstat().st_ino)
            frozen = (journal.read_bytes(), marker.lstat().st_ino, marker.read_bytes(), state[7].read_bytes(),
                os.readlink(state[2]), stage.lstat().st_ino, stage.read_bytes())
            with self.assertRaisesRegex(LOAD.LoadError, "DHCP.*stage.*owner.*HOLD|unplanned.*stage.*HOLD|DHCP.*owner.*HOLD"):
                LOAD.restore_setup_switch_a_disk(q, guard=guard, confirmed=True)
            self.assertEqual(frozen, (journal.read_bytes(), marker.lstat().st_ino, marker.read_bytes(), state[7].read_bytes(),
                os.readlink(state[2]), stage.lstat().st_ino, stage.read_bytes()))
        state[-1].start.assert_not_called()

    def _committed_q_group_restored_dhcp_owner_fault(self, name):
        state, _context, guard, _token, _inputs = self._prepare_published_q_for_stopped_preflight(dhcp=True)
        q, journal = state[1], state[-3]
        runtime = self.root.resolve() / "private-etc-dhcp"
        names = ("dhcpd.conf", "dhcpd_eth.hosts", "dhcpd_ib.hosts", "dhcpd_nvl.hosts")
        mappings = {q / "independent-dhcp-B" / item: runtime / item for item in names}
        with mock.patch.object(LOAD, "active_managed_services", return_value=()), \
                mock.patch.object(LOAD, "dhcp_file_mappings", return_value=mappings):
            LOAD.restore_setup_switch_a_disk(q, guard=guard, confirmed=True)
            marker = journal.parent / ".setup-switch-a-restore.json"
            path, held = runtime / name, self.root / "independent-held-restored-dhcp-owner"
            metadata = path.lstat()
            link = path.is_symlink()
            payload = os.readlink(path) if link else path.read_bytes()
            path.rename(held)
            if link:
                path.symlink_to(payload)
            else:
                path.write_bytes(payload)
                path.chmod(stat.S_IMODE(metadata.st_mode))
            os.utime(path, ns=(metadata.st_atime_ns, metadata.st_mtime_ns), follow_symlinks=False)
            self.assertNotEqual(held.lstat().st_ino, path.lstat().st_ino)
            frozen = (journal.lstat().st_ino, journal.read_bytes(), marker.lstat().st_ino, marker.read_bytes(),
                      state[7].read_bytes(), (self.ztp / "ztp-bootstrap_oob.sh").read_bytes(),
                      path.lstat().st_ino, os.readlink(path) if link else path.read_bytes())
            with self.assertRaisesRegex(LOAD.LoadError, "DHCP.*(owner|stage).*HOLD"):
                LOAD.restore_setup_switch_a_disk(q, guard=guard, confirmed=True)
            self.assertEqual(frozen, (journal.lstat().st_ino, journal.read_bytes(), marker.lstat().st_ino,
                marker.read_bytes(), state[7].read_bytes(), (self.ztp / "ztp-bootstrap_oob.sh").read_bytes(),
                path.lstat().st_ino, os.readlink(path) if link else path.read_bytes()))
        state[-1].start.assert_not_called()

    def test_setup_wal_original_dhcp_backup_boolean_identity_is_rejected(self):
        state, _context, _guard, _token, _inputs = self._prepare_published_q_for_stopped_preflight(dhcp=True)
        original = state[-3].read_bytes()
        envelope = json.loads(original)
        envelope["body"]["dhcp_transaction"]["backup_inventory"]["leaves"]["dhcpd.conf"][0] = True
        envelope["sha256"] = hashlib.sha256(LOAD._setup_switch_canonical_payload(envelope["body"])).hexdigest()
        with self.assertRaisesRegex(ValueError, "DHCP backup leaf owner"):
            LOAD._decode_setup_switch_journal(LOAD._setup_switch_canonical_payload(envelope))
        self.assertEqual(original, state[-3].read_bytes())
        # A legacy reader contract must remain visibly unqualified, not gain
        # a new inventory by sampling today's backup namespace.
        envelope = json.loads(original)
        del envelope["body"]["dhcp_transaction"]["backup_inventory"]
        envelope["sha256"] = hashlib.sha256(LOAD._setup_switch_canonical_payload(envelope["body"])).hexdigest()
        decoded = LOAD._decode_setup_switch_journal(LOAD._setup_switch_canonical_payload(envelope))
        self.assertNotIn("backup_inventory", decoded["body"]["dhcp_transaction"])

    def _committed_q_group_dhcp_backup_fault(self, fault):
        state, _context, guard, _token, _inputs = self._prepare_published_q_for_stopped_preflight(dhcp=True)
        q, journal = state[1], state[-3]
        runtime = self.root.resolve() / "private-etc-dhcp"
        names = ("dhcpd.conf", "dhcpd_eth.hosts", "dhcpd_ib.hosts", "dhcpd_nvl.hosts")
        mappings = {q / "independent-dhcp-B" / name: runtime / name for name in names}
        with mock.patch.object(LOAD, "active_managed_services", return_value=()), \
                mock.patch.object(LOAD, "dhcp_file_mappings", return_value=mappings):
            LOAD.restore_setup_switch_q_publication(q, guard=guard, confirmed=True)
            body = json.loads(journal.read_bytes())["body"]
            directory = Path(body["dhcp_transaction"]["body"]["backup"]["path"])
            backup = directory / ("dhcpd_eth.hosts" if fault == "link" else "dhcpd.conf")
            metadata = backup.lstat()
            payload = os.readlink(backup) if fault == "link" else backup.read_bytes()
            held = self.root / "independent-held-original-dhcp-backup"
            if fault == "directory":
                directory.rename(held)
                shutil.copytree(held, directory, symlinks=True)
                self.assertNotEqual(held.lstat().st_ino, directory.lstat().st_ino)
            else:
                backup.rename(held)
                if fault == "link":
                    backup.symlink_to(payload)
                else:
                    backup.write_bytes(payload)
                    backup.chmod(stat.S_IMODE(metadata.st_mode))
                os.utime(backup, ns=(metadata.st_atime_ns, metadata.st_mtime_ns), follow_symlinks=False)
                self.assertNotEqual(held.lstat().st_ino, backup.lstat().st_ino)
            def unknown_leaf():
                return (backup.lstat().st_ino, os.readlink(backup) if fault == "link" else backup.read_bytes())
            evidence = (state[2].lstat().st_ino, os.readlink(state[2]), state[7].read_bytes(),
                        (self.ztp / "ztp-bootstrap_oob.sh").read_bytes(), journal.read_bytes(),
                        unknown_leaf())
            with self.assertRaisesRegex(LOAD.LoadError, "DHCP.*backup.*(owner|inventory).*HOLD"):
                LOAD.restore_setup_switch_a_disk(q, guard=guard, confirmed=True)
            self.assertEqual(evidence, (state[2].lstat().st_ino, os.readlink(state[2]), state[7].read_bytes(),
                (self.ztp / "ztp-bootstrap_oob.sh").read_bytes(), journal.read_bytes(),
                unknown_leaf()))
        state[-1].start.assert_not_called()

    def test_committed_q_group_managed_keys_share_one_original_restore_stage(self):
        state, context, guard, token, _inputs = self._prepare_published_q_for_stopped_preflight(
            managed_key=True, partial_runtime=True)
        journal, q = state[-3], state[1]
        original_wal = (journal.lstat().st_ino, journal.read_bytes())
        sources = {context.project / name: (context.project / name).read_bytes()
                   for name in ("laptop.pub", "mgmt-server.pub")}
        with mock.patch.object(LOAD, "active_managed_services", return_value=()), \
                mock.patch.object(LOAD, "_runtime_service_action") as service:
            result = LOAD.restore_setup_switch_a_disk(q, guard=guard, confirmed=True)
            self.assertEqual("restored-p-a-group-stopped-wal-retained", result)
            marker = journal.parent / ".setup-switch-a-restore.json"
            plan = json.loads(marker.read_bytes())
            own = {}
            for name in ("laptop.pub", "mgmt-server.pub"):
                path = (self.ztp / "config/publickey" / name).parent.resolve() / name
                row = plan["runtime"][str(path)]
                self.assertNotIn(str(path), plan["setup"], "one name must not acquire two restore owners")
                self.assertFalse(os.path.lexists(row["stage"]["path"]))
                self.assertEqual(row["before"]["target"], os.readlink(path))
                self.assertEqual(row["stage"]["file"]["identity"][:8],
                                 list(LOAD._dhcp_a_preimage_receipt_identity(path.lstat()))[:8])
                own[path] = (path.lstat().st_ino, os.readlink(path))
            frozen_plan = (marker.lstat().st_ino, marker.read_bytes())
            LOAD.close_setup_switch_publication_bundle(token)
            self.assertEqual(result, LOAD.restore_setup_switch_a_disk(q, guard=guard, confirmed=True))
            self.assertEqual(own, {path: (path.lstat().st_ino, os.readlink(path)) for path in own})
            self.assertEqual(original_wal, (journal.lstat().st_ino, journal.read_bytes()))
            self.assertEqual(frozen_plan, (marker.lstat().st_ino, marker.read_bytes()))
            self.assertEqual(sources, {path: path.read_bytes() for path in sources})
            service.assert_not_called()

