    def _prepare_q_manifest_publication(self, *, seed_q_publication=False, q_local=False,
                                        original_a_policy=None, original_a_images=False, q_created=False, prefix=False,
                                        managed_key=False, prefix_change=False, qualified_a_health=False):
        state, context = self._prepare_persisted_a_runtime_switch(seed_q_publication=seed_q_publication,
            original_upgrade_policy=original_a_policy, original_images=original_a_images, prefix=prefix,
            managed_key=managed_key, qualified_a_health=qualified_a_health)
        journal, descriptor, backend = state[-3:]
        guard = dict(deployment_lock_descriptor=descriptor, services_quiesced=True, runtime_backend=backend)
        if prefix_change:
            settings = LOAD.replace(LOAD.load_global(self.global_file), ztp_prefix=prefix_change if isinstance(prefix_change, str) else "/q-prefix")
            with mock.patch.object(LOAD, "active_managed_services", return_value=()):
                LOAD.prepare_setup_switch_prefix_transaction(settings, guard=guard)
        if q_local:
            latest, releases = self._q_local_latest_fixture(state[1])
            with mock.patch.object(LOAD, "active_managed_services", return_value=()):
                LOAD.register_setup_switch_q_local_latest(journal, latest, releases[1], **guard)
            latest.unlink()
            latest.symlink_to(releases[1].name)
        state[2].unlink()
        state[2].symlink_to(os.path.relpath(state[5], state[2].parent))
        state[3].unlink()
        key_links = []
        if managed_key or qualified_a_health:
            for name in ("laptop.pub", "mgmt-server.pub"):
                link = self.ztp / "config/publickey" / name
                link.unlink()
                link.symlink_to(os.path.relpath(state[1] / name, link.parent))
                key_links.append(link)
        q_link = self.ztp / "config/independent-q-only-parent/operator.pub"
        if q_created:
            target = state[1] / "independent-q-operator.pub"
            target.write_bytes(b"independent Q-only operator\n")
            with mock.patch.object(LOAD, "active_managed_services", return_value=()), \
                    mock.patch.object(SETUP, "ZTP", str(self.ztp)), \
                    mock.patch.object(SETUP, "_SETUP_SWITCH_WAL_CONTEXT", (vars(LOAD), descriptor)):
                SETUP._SetupLinkTransaction([]).ensure_directory(str(q_link.parent))
                LOAD.register_setup_switch_journal_link(journal, q_link, target, **guard)
                q_link.symlink_to(os.path.relpath(target, q_link.parent))
        manifest = ("# setup manifest — proj: " + str(state[1].resolve()) + "\n"
                    + str(state[2]) + "\n"
                    + "".join(str(path) + "\n" for path in key_links)
                    + (str(q_link) + "\n" if q_created else "")
                    + (str(self.ztp / "image/cumulus/cumulus-linux-5.12.0-mlx-amd64.bin") + "\n"
                       if original_a_images else "")).encode()
        with mock.patch.object(LOAD, "active_managed_services", return_value=()):
            LOAD.register_setup_switch_manifest(journal, manifest, _publish_manifest=True, **guard)
        return state, context, guard

    def test_publication_wal_freezes_original_q_manifest_and_shared_link_owners(self):
        state, _context, guard = self._prepare_q_manifest_publication()
        candidates = private_publication_candidates(LOAD, state[1])
        with mock.patch.object(LOAD, "active_managed_services", return_value=()):
            token = LOAD.register_setup_switch_publication_bundle(*candidates, guard=guard)
            self.addCleanup(LOAD.close_setup_switch_publication_bundle, token)
            shared = json.loads(token["payload"])["body"]["publication_bundle"]["shared_setup"]
            self.assertEqual(state[7].lstat().st_ino, shared["manifest"]["identity"][1])
            self.assertEqual(state[2].lstat().st_ino, shared["links"][str(state[2])]["identity"][1])
            self.assertEqual(os.readlink(state[2]), shared["links"][str(state[2])]["target"])
            self.assertIsNone(shared["links"][str(state[3])])
            original = state[7].read_bytes()
            held = state[7].with_name("independent-held-q-manifest")
            state[7].rename(held)
            state[7].write_bytes(original)
            state[7].chmod(0o644)
            with self.assertRaisesRegex(LOAD.LoadError, "HOLD"):
                LOAD.require_setup_switch_publication_bundle(token, guard=guard)
            self.assertEqual(original, state[7].read_bytes())
            self.assertTrue(candidates[0].temporary.is_file())
            self.assertFalse(candidates[0].destination.exists())

