        raced = []

        def replaced_after_missing(path, *args, **kwargs):
            if path == physical_leaf and not raced:
                raced.append(True)
                raise FileNotFoundError("old key leaf disappeared before name was rebound")
            return real_lstat(path, *args, **kwargs)

