    def _write_setup_manifest(self, project: Path, links: dict[Path, Path]) -> Path:
        manifest = self.ztp / ".setup_manifest"
        manifest.parent.mkdir(parents=True, exist_ok=True)
        rows = [f"# setup manifest — proj: {project}\n"]
        for link, target in sorted(links.items(), key=lambda item: str(item[0])):
            link.parent.mkdir(parents=True, exist_ok=True)
            if os.path.lexists(link):
                link.unlink()
            link.symlink_to(os.path.relpath(target.resolve(), link.parent.resolve()))
            rows.append(f"{link}\n")
        manifest.write_text("".join(rows), encoding="utf-8")
        return manifest

    def _prepare_cross_project_setup_crash(self, *, freeze_q_links=True, q_parent_payload=None, extra_old_links=None):
        """Freeze P before a Q setup child can rewrite any managed link."""
        old_project = self.project.resolve()
        new_project = self.root / "DAY0-Prepare/new"
        new_project.mkdir()
        new_target = new_project / "01-global.yaml"
        new_target.write_bytes(b"Q global\n")
        new_only_target = new_project / "new-only.csv"
        new_only_target.write_bytes(b"Q only\n")
        if q_parent_payload is not None:
            q_parent = new_project / "99-output-ztp/current-release.json"
            q_parent.parent.mkdir()
            q_parent.write_bytes(q_parent_payload)
        old_status = old_project / "99-output-ztp"
        old_status.mkdir(parents=True, exist_ok=True)
        common = self.ztp / "config/cumulus/template/01-global.yaml"
        old_only = self.ztp / "status"
        new_only = self.ztp / "config/cumulus/template/new-only.csv"
        manifest = self._write_setup_manifest(
            old_project, {common: self.global_file, old_only: old_status, **(extra_old_links or {})},
        )
        old_manifest = manifest.read_bytes()
        old_links = {path: os.readlink(path) for path in (common, old_only, *(extra_old_links or {}))}
        lock_path = self.root / ".deployment.lock"
        constants = mock.patch.multiple(
            LOAD, HTTP_ROOT=self.root, MANIFEST=manifest,
            IMAGE_DIR=self.root / "image", DEPLOYMENT_LOCK=lock_path,
        )
        constants.start()
        self.addCleanup(constants.stop)
        setup_manifest = mock.patch.object(SETUP, "MANIFEST_FILE", str(manifest))
        setup_manifest.start()
        self.addCleanup(setup_manifest.stop)
        descriptor = LOAD.acquire_deployment_lock(exclusive=True)
        self.addCleanup(LOAD.release_deployment_lock, descriptor)
        backend = SimpleNamespace(name="supervisor", start=mock.Mock())
        with mock.patch.object(LOAD, "active_managed_services", return_value=()):
            journal = LOAD.prepare_setup_switch_journal(
                old_project, new_project,
                expected_new_links=(
                    {common: new_target, new_only: new_only_target}
                    if freeze_q_links else {}
                ),
                allow_late_q_values=not freeze_q_links,
                deployment_lock_descriptor=descriptor,
                services_quiesced=True, runtime_backend=backend,
            )
        self.assertTrue(journal.is_file())
        self.assertEqual(0o600, stat.S_IMODE(journal.stat().st_mode))
        return (
            old_project, new_project, common, old_only, new_only,
            new_target, new_only_target, manifest, old_manifest, old_links,
            journal, descriptor, backend,
        )

    def test_setup_link_restore_preserves_foreign_stage_before_publish_or_cleanup(self):
        for kind in ("publish", "hold"):
            with self.subTest(kind=kind):
                path = self.ztp / f"private-managed-link-{kind}"
                path.symlink_to("independent-Q-target")
                before = (path.lstat().st_ino, os.readlink(path))
                original = Path.symlink_to
                injected = []

                def stage_replaced(stage, raw, *args, **kwargs):
                    result = original(stage, raw, *args, **kwargs)
                    if stage.name.startswith(f".{path.name}.setup-rollback.") and not injected:
                        held = stage.with_name(f"held-original-link-stage-{kind}")
                        stage.rename(held)
                        if kind == "publish":
                            original(stage, "independent-foreign-target")
                        else:
                            stage.write_bytes(b"independent foreign stage evidence\n")
                        injected.append((stage, stage.lstat().st_ino, held))
                    return result

                def authority():
                    if kind == "hold" and injected:
                        raise LOAD.LoadError("independent authority rejection after staging")

                caught = None
                with mock.patch.object(Path, "symlink_to", stage_replaced):
                    try:
                        LOAD._atomic_restore_setup_link(path, "independent-P-target", require_authority=authority)
                    except LOAD.LoadError as exc:
                        caught = exc
                self.assertEqual(1, len(injected), "link staging injection was not reached")
                self.assertIsInstance(caught, LOAD.LoadError)
                self.assertEqual(before, (path.lstat().st_ino, os.readlink(path)))
                stage, inode, held = injected[0]
                self.assertTrue(os.path.lexists(stage), "cleanup consumed the foreign stage")
                self.assertEqual(inode, stage.lstat().st_ino)
                self.assertEqual("independent-P-target", os.readlink(held))
                if kind == "publish":
                    self.assertEqual("independent-foreign-target", os.readlink(stage))
                else:
                    self.assertEqual(b"independent foreign stage evidence\n", stage.read_bytes())
                stage.unlink()
                held.unlink()
                path.unlink()  # Only independently identified private fixture objects.

    def test_setup_manifest_restore_syncs_final_mode_before_replace(self) -> None:
        manifest = self.ztp / ".setup_manifest"
        manifest.write_bytes(b"uncommitted Q manifest\n")
        state = SimpleNamespace(manifest=b"independent P manifest\n", manifest_mode=0o640)
        events = []
        real_sync, real_replace = os.fsync, os.replace

        def sync(descriptor):
            metadata = os.fstat(descriptor)
            if stat.S_ISREG(metadata.st_mode):
                self.assertEqual(0o640, stat.S_IMODE(metadata.st_mode),
                                 "final P permissions must precede file fsync")
                events.append("file-synced")
            else:
                self.assertEqual(["file-synced", "replaced"], events)
                events.append("parent-synced")
            return real_sync(descriptor)

        def replace(source, destination):
            self.assertEqual(["file-synced"], events)
            self.assertEqual(state.manifest, Path(source).read_bytes())
            events.append("replaced")
            return real_replace(source, destination)

        with mock.patch.object(LOAD, "MANIFEST", manifest), \
                mock.patch.object(LOAD.os, "fsync", side_effect=sync), \
                mock.patch.object(LOAD.os, "replace", side_effect=replace):
            LOAD._atomic_restore_setup_manifest(state)
        self.assertEqual(["file-synced", "replaced", "parent-synced"], events)
        self.assertEqual(state.manifest, manifest.read_bytes())
        self.assertEqual(0o640, stat.S_IMODE(manifest.stat().st_mode))

    def test_setup_manifest_restore_rejects_foreign_staged_inode_or_bytes(self):
        for kind in ("inode", "bytes"):
            with self.subTest(kind=kind):
                manifest = self.ztp / ".setup_manifest"
                manifest.write_bytes(b"independent mixed Q manifest\n")
                target_before = (manifest.lstat().st_ino, manifest.read_bytes())
                retained = self.ztp / "held-original-manifest-stage"
                state = SimpleNamespace(manifest=b"independent frozen P manifest\n", manifest_mode=0o640)
                sync = os.fsync
                injected = []

                def foreign_stage(fd):
                    result = sync(fd)
                    info = os.fstat(fd)
                    stages = list(manifest.parent.glob(f".{manifest.name}.rollback.*"))
                    for path in stages:
                        if path.lstat().st_ino == info.st_ino and not injected:
                            if kind == "inode":
                                path.rename(retained)
                            path.write_bytes(b"independent foreign staged bytes\n")
                            path.chmod(0o640)
                            injected.append((path, path.lstat().st_ino))
                    return result

                caught = None
                with mock.patch.object(LOAD, "MANIFEST", manifest), \
                        mock.patch.object(os, "fsync", side_effect=foreign_stage):
                    try:
                        LOAD._atomic_restore_setup_manifest(state)
                    except LOAD.LoadError as exc:
                        caught = exc
                self.assertEqual(1, len(injected), "owned staged manifest was not reached")
                self.assertIsInstance(caught, LOAD.LoadError, "foreign staging must HOLD before replace")
                self.assertEqual(target_before, (manifest.lstat().st_ino, manifest.read_bytes()))
                path, owner = injected[0]
                self.assertEqual(owner, path.lstat().st_ino, "cleanup removed a foreign stage")
                self.assertEqual(b"independent foreign staged bytes\n", path.read_bytes())
                if kind == "inode":
                    self.assertEqual(state.manifest, retained.read_bytes())
                    retained.unlink()
                path.unlink()  # Only this test's independently identified injected object.

