    def test_cross_project_failure_restore_uses_wal_before_runtime_receipt(self) -> None:
        (*state, journal, descriptor, backend) = self._prepare_cross_project_setup_crash(freeze_q_links=False)
        old_project, project, common = state[:3]
        snapshot = LOAD.snapshot_active_setup_state(expected_project=old_project)
        context = LOAD.CrossProjectRollbackContext(
            old_project, "generations/aaaaaaaaaaaaaaaaaaaa",
            old_project / "99-output-ztp/rollback-receipts/aaaaaaaaaaaaaaaaaaaa", snapshot,
        )
        directory = self.ztp / "config/new-key-root"
        link = directory / "operator.pub"
        target = project / "operator.pub"
        target.write_bytes(b"Q key fixture\n")
        with mock.patch.object(LOAD, "active_managed_services", return_value=()), \
                mock.patch.object(SETUP, "ZTP", str(self.ztp)), \
                mock.patch.object(SETUP, "_SETUP_SWITCH_WAL_CONTEXT", (vars(LOAD), descriptor)):
            SETUP._SetupLinkTransaction([]).ensure_directory(str(directory))
            LOAD.register_setup_switch_journal_link(
                journal, link, target, deployment_lock_descriptor=descriptor,
                services_quiesced=True, runtime_backend=backend,
            )
            link.symlink_to(os.path.relpath(target, link.parent))
            LOAD.register_setup_switch_journal_link(
                journal, common, state[5], deployment_lock_descriptor=descriptor,
                services_quiesced=True, runtime_backend=backend,
                allow_existing_exact=True,
            )
            common.unlink()
            common.symlink_to(os.path.relpath(state[5], common.parent))

            evidence = journal.read_bytes()
            def restore_runtime(*args, **kwargs):
                self.assertFalse(os.path.lexists(directory), "runtime restore bypassed owned-directory WAL")
                self.assertTrue(journal.is_file(), "runtime phase must retain recovery authority")
                self.assertEqual(evidence, journal.read_bytes())
                self.assertEqual(snapshot.manifest, state[7].read_bytes())
                self.assertEqual(snapshot.links, {path: os.readlink(path) for path in snapshot.links})

            with mock.patch.object(LOAD, "restore_runtime_rollback_receipt", side_effect=restore_runtime) as runtime:
                LOAD.restore_cross_project_rollback_context(
                    context, current_project=project, deployment_lock_descriptor=descriptor,
                    services_quiesced=True, runtime_backend=backend,
                )
            runtime.assert_called_once()
        self.assertFalse(os.path.lexists(journal), "verified complete restore must retire its own WAL")
        backend.start.assert_not_called()

    def _prepare_persisted_a_runtime_switch(self, *, managed_key=False, prefix=False,
                                          original_upgrade_policy=None, qualified_inputs=False,
                                          seed_q_publication=False, original_images=False, qualified_a_health=False):
        if prefix or managed_key:
            # A marker is lexical as well as physical authority. Use the same
            # canonical private deployment paths as the real cold LOAD child;
            # managed key WAL row names must use those paths too.
            self.root, self.ztp = self.root.resolve(), self.ztp.resolve()
            namespace = mock.patch.object(LOAD, "ZTP_DIR", self.ztp)
            namespace.start()
            self.addCleanup(namespace.stop)
        private_root = mock.patch.object(LOAD, "HTTP_ROOT", self.root.resolve())
        private_root.start()
        self.addCleanup(private_root.stop)
        document = yaml.safe_load(self.global_file.read_text())
        document["common"]["mgmt"]["http"]["http_root"] = str(self.root.resolve())
        if original_images:
            document["switches"][0]["eth"]["version"] = "5.12.0"
            basename = "cumulus-linux-5.12.0-mlx-amd64.bin"
            source = self.root / "image" / basename
            source.parent.mkdir(exist_ok=True)
            source.write_bytes(b"#!/bin/sh\n" + b"independent-original-A-image\n" * 45000)
            published = self.ztp / "image/cumulus" / basename
            published.parent.mkdir(parents=True)
            published.symlink_to(os.path.relpath(source, published.parent))
        marker_patch = mock.patch.object(LOAD, "ZTP_PREFIX_MARKER", self.root / ".ztp-prefix-publication.json")
        marker_patch.start()
        self.addCleanup(marker_patch.stop)
        if prefix:
            document["common"]["mgmt"]["ztp"]["ztp_url_prefix"] = "/r22-prefix"
            if prefix != "missing-link":
                (self.root / "r22-prefix").symlink_to("ztp")
            LOAD.ZTP_PREFIX_MARKER.write_text(json.dumps({
                "schema_version": 1, "prefix": "/r22-prefix",
                "path": str(self.root.resolve() / "r22-prefix"), "target": str(self.ztp),
            }))
        self.global_file.write_text(yaml.safe_dump(document, sort_keys=False))
        if qualified_a_health:
            original_upgrade_policy = "disabled"
        if original_upgrade_policy is not None or qualified_inputs or qualified_a_health:
            # Existing minimal disk-only fixtures stay unchanged. Selection
            # fixtures freeze a complete, independently literal subnet CSV.
            self.subnet_file.write_text(
                "shared_network,subnet,netmask,range_start,range_end,routers,"
                "ztp_service_ip,cumulus_profile,nvos_ztp\n"
                "net,192.0.2.0,255.255.255.0,192.0.2.20,192.0.2.30,192.0.2.1,"
                "192.0.2.2,oob,no\n")
        if managed_key:
            generation, receipt = self._publish_a_with_managed_key_receipt()
        else:
            _parent, generation, receipt = self._publish_a_with_runtime_rollback_receipt(
                original_upgrade_policy=original_upgrade_policy, qualified_health=qualified_a_health)
        extra_images = ({published: source} if original_images else {})
        extra_keys = ({self.ztp / "config/publickey" / name: self.project / name
                       for name in ("laptop.pub", "mgmt-server.pub")} if managed_key or qualified_a_health else {})
        state = self._prepare_cross_project_setup_crash(extra_old_links={**extra_images, **extra_keys})
        p, q, common = state[:3]
        journal, descriptor, backend = state[-3:]
        # Replace only this fixture's untouched legacy WAL, before any Q write.
        journal.unlink()
        for link in extra_keys:
            (q / link.name).write_bytes(("independent Q key: " + link.name + "\n").encode())
        if seed_q_publication:
            parent, report, prior_generation = private_publication_candidates(LOAD, q)
            LOAD.commit_prepared_release(parent)
            LOAD.generation_report.commit_prepared_generation_report(report)
            LOAD.commit_pinned_generation(q, prior_generation, expected_current=None)
            for name in ("current-release.json", "generation-report.json", "current"):
                os.utime(q / "99-output-ztp" / name,
                         ns=(1700000000123456789, 1700000000123456789), follow_symlinks=False)
            self._original_q_publication = {
                "parent": parent.destination.read_bytes(),
                "report": report.destination.read_bytes(),
                "selector": os.readlink(q / "99-output-ztp/current")}
        context = LOAD.CrossProjectRollbackContext(
            p, "generations/" + generation.name, receipt.resolve(),
            LOAD.snapshot_active_setup_state(expected_project=p),
        )
        with mock.patch.object(LOAD, "active_managed_services", return_value=()):
            LOAD.prepare_setup_switch_journal(
                p, q, expected_new_links={common: state[5], **extra_images,
                                         **{path: q / path.name for path in extra_keys}},
                deployment_lock_descriptor=descriptor, services_quiesced=True,
                runtime_backend=backend, runtime_rollback_context=context,
            )
        return state, context

